begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('aa000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','history-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,6) n;
insert into public.staff_users(user_id,role) values('aa000000-0000-4000-8000-000000000001','admin'),('aa000000-0000-4000-8000-000000000002','office'),('aa000000-0000-4000-8000-000000000003','technician'),('aa000000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('ca000000-0000-4000-8000-000000000001','Klient historii'),('ca000000-0000-4000-8000-000000000002','Obcy klient');
insert into public.staff_customer_assignments(user_id,customer_id) values('aa000000-0000-4000-8000-000000000003','ca000000-0000-4000-8000-000000000001'),('aa000000-0000-4000-8000-000000000004','ca000000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('aa000000-0000-4000-8000-000000000005','ca000000-0000-4000-8000-000000000001');
create function pg_temp.history() returns jsonb language sql as $$select public.customer_activity('ca000000-0000-4000-8000-000000000001','crm_task',1)$$;
create function pg_temp.change(n integer,who integer,day text) returns jsonb language sql as $$select public.change_crm_task_plan('ca000000-0000-4000-8000-000000000001','da000000-0000-4000-8000-000000000001',n,('aa000000-0000-4000-8000-'||lpad(who::text,12,'0'))::uuid,day)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select public.save_crm_record('ca000000-0000-4000-8000-000000000001','tasks','da000000-0000-4000-8000-000000000001',null,'{"title":"Uzgodnić plan","description":"PRIVATE DESCRIPTION","kind":"general","dueOn":"2026-11-01","assigneeId":"aa000000-0000-4000-8000-000000000003","contactId":null,"state":"todo","result":"PRIVATE RESULT"}');
select is(pg_temp.history()->>'total','1','Creation is one timeline event');
select ok(not(pg_temp.history()->'items'->0 ? 'planChange'),'Creation has no plan difference');
select pg_temp.change(0,4,'2026-11-05');
select is((select e->'planChange'->>'actorLabel' from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),'history-2@example.invalid','Office sees audit actor');
select is((select e->'planChange'->'dueOn' from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),'{"from":"2026-11-01","to":"2026-11-05"}'::jsonb,'Previous and new dates from audit');
select is((select e->'planChange'->'assignee' from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),'{"fromLabel":"history-3@example.invalid","toLabel":"history-4@example.invalid"}'::jsonb,'Previous and new person labels');
select is((select e->>'title' from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),'Zmieniono plan zadania CRM','Plan change named explicitly');
select ok(pg_temp.history()::text not like '%PRIVATE%','No description or result exposed');
select ok(pg_temp.history()::text not like '%old_data%','No raw audit payload');
select ok(pg_temp.history()::text not like '%aa000000%','No user identifiers exposed');
select pg_temp.change(0,4,'2026-11-05');
select is(pg_temp.history()->>'total','2','Identical retry has no extra timeline event');
select pg_temp.change(1,4,'2026-11-06');
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e->'planChange'->'assignee'='null'::jsonb and e->'planChange'->'dueOn'->>'to'='2026-11-06'),1,'Date only change has no redundant person entry');
select pg_temp.change(2,3,'2026-11-06');
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e->'planChange'->'dueOn'='null'::jsonb and e->'planChange'->'assignee'->>'toLabel'='history-3@example.invalid'),1,'Person only change has no redundant date entry');
select public.crm_task_progress('ca000000-0000-4000-8000-000000000001','da000000-0000-4000-8000-000000000001',3,'in_progress','PRIVATE RESULT');
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),3,'Progress does not create plan details');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),3,'Admin sees plan history');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000003',true);
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e ? 'planChange'),0,'Technician sees no person or plan comparison');
select is(pg_temp.history()->>'total','2','Technician history keeps existing assignment visibility');
select throws_ok($$select public.customer_activity('ca000000-0000-4000-8000-000000000002','crm_task',1)$$,'42501',null,'Unassigned customer denied');
reset role;
update public.audit_logs set actor_id=null where table_name='crm_tasks' and row_id='da000000-0000-4000-8000-000000000001' and action='UPDATE';
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e->'planChange'->>'actorLabel'='Niedostępny użytkownik'),3,'Missing audit actor has honest fallback');
-- Full form saves are also represented, even if plan and progress change together.
select public.save_crm_record('ca000000-0000-4000-8000-000000000001','tasks','da000000-0000-4000-8000-000000000001',4,'{"title":"Uzgodnić plan","description":"PRIVATE DESCRIPTION","kind":"general","dueOn":"2026-11-07","assigneeId":"aa000000-0000-4000-8000-000000000003","contactId":null,"state":"done","result":"PRIVATE RESULT"}');
select is((select e->>'title' from jsonb_array_elements(pg_temp.history()->'items') e where e->'planChange'->'dueOn'->>'to'='2026-11-07'),'Wykonano zadanie CRM','Combined change retains progress event title');
select is((select count(*)::int from jsonb_array_elements(pg_temp.history()->'items') e where e->'planChange'->'dueOn'->>'to'='2026-11-07'),1,'Full form plan change appears once');
select is(public.customer_activity('ca000000-0000-4000-8000-000000000001','customer',1)->>'total','1','Other kind filters unaffected');
select throws_ok($$select public.customer_activity('ca000000-0000-4000-8000-000000000001','crm_task',0)$$,'22023',null,'Invalid page rejected');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000005',true);
select throws_ok($$select pg_temp.history()$$,'42501',null,'Portal user denied internal history');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000006',true);
select throws_ok($$select pg_temp.history()$$,'42501',null,'No role user denied');
reset role;
insert into public.account_access(user_id,blocked) values('aa000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.history()$$,'42501',null,'Blocked office denied');
reset role;
set local role anon;
select throws_ok($$select public.customer_activity('ca000000-0000-4000-8000-000000000001','crm_task',1)$$,'42501',null,'Anonymous denied execution');
reset role;
-- Audit ordering and pagination are stable and preserve one record per write.
update public.account_access set blocked=false where user_id='aa000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select public.save_crm_record('ca000000-0000-4000-8000-000000000001','tasks','da000000-0000-4000-8000-000000000002',null,'{"title":"Stronicowane zadanie","description":"","kind":"general","dueOn":"2026-11-01","assigneeId":"aa000000-0000-4000-8000-000000000003","contactId":null,"state":"todo","result":""}');
select public.change_crm_task_plan('ca000000-0000-4000-8000-000000000001','da000000-0000-4000-8000-000000000002',n-1,'aa000000-0000-4000-8000-000000000003',to_char(date '2026-11-01'+n,'YYYY-MM-DD')) from generate_series(1,21) n;
select is(pg_temp.history()->>'total','28','Total counts events without duplication');
select is(jsonb_array_length(pg_temp.history()->'items'),20,'First page limited to twenty');
select is(jsonb_array_length(public.customer_activity('ca000000-0000-4000-8000-000000000001','crm_task',2)->'items'),8,'Second page retains remaining changes');
select is((select count(distinct e->>'id')::int from jsonb_array_elements((pg_temp.history()->'items')||(public.customer_activity('ca000000-0000-4000-8000-000000000001','crm_task',2)->'items')) e),28,'Pages do not overlap');
select * from finish();
rollback;
